SELECT product_id FROM ( SELECT product_id, store_id, IF ( @prev_store_id = store_id, @row_num := @row_num + 1, @row_num := 1 ) AS row_number, @prev_store_id := store_id FROM pt_product_index CROSS JOIN ( SELECT @row_num := 0, @prev_store_id := NULL ) vars
store_id in
#{store_id}
and product_state_id = #{product_state_id}
ORDER BY store_id, product_add_time DESC, product_id DESC ) grouped_table
row_number <= #{row_number}
ORDER BY store_id, product_id DESC;

SELECT product_id
FROM (
SELECT
product_id,
store_id,
ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY product_id DESC) AS row_num
FROM pt_product_index


        store_id in

            #{store_id}



        and product_state_id = #{product_state_id}


) AS RankedProducts


        row_num <= #{row_number}


ORDER BY store_id ASC, product_id DESC;
